<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import {api,date,notify,type Row} from '../lib'
import Modal from './Modal.vue'
const emit=defineEmits<{configure:[]}>()
const allTime=ref(new URLSearchParams(location.hash.split('?')[1]||'').get('all_time')==='true')
const data=ref<Row>({items:[],blocks:[],summary:{},categories:[]}),q=ref(''),severity=ref(''),category=ref(''),state=ref('pending'),start=ref(''),end=ref(''),page=ref(1),panel=ref('events'),loading=ref(false),busy=ref(false),error=ref(''),detail=ref<Row|null>(null),confirmation=ref<Row|null>(null)
let controller:AbortController|undefined
const names:Row={login_failed:'登录校验失败',login_rate:'登录限流',permission_denied:'权限拦截',rate_limit:'请求限流',order_rate:'申请限流',redeem_rate:'兑换限流'}
async function load(){controller?.abort();const request=new AbortController();controller=request;loading.value=true;error.value='';try{const value=await api('/admin/risk?'+new URLSearchParams({all_time:String(allTime.value),q:q.value,severity:severity.value,category:category.value,state:state.value,start:start.value,end:end.value,page:String(page.value),page_size:'50'}),'GET',undefined,{},request.signal);if(controller===request){data.value=value;start.value=value.start;end.value=value.end}}catch(e){if((e as Error).name!=='AbortError')error.value=(e as Error).message}finally{if(controller===request)loading.value=false}}
function filter(){allTime.value=false;page.value=1;void load()}
async function resolve(id:number){busy.value=true;try{await api('/admin/risk/'+id+'/resolve','POST',{});notify('已标记核查，访问限制保持原状');await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function release(){if(!confirmation.value)return;busy.value=true;try{await api('/admin/blocks/'+encodeURIComponent(confirmation.value.ip),'DELETE');confirmation.value=null;notify('访问限制已解除');await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load);onUnmounted(()=>controller?.abort())
</script>
<template><section class="risk-monitor">
 <div class="risk-heading"><p class="muted">集中查看异常访问与当前限制，核查记录与解除限制分别处理。</p><div class="actions"><button class="btn secondary" :disabled="loading" @click="load">刷新</button><button class="btn primary" @click="emit('configure')">风控配置</button></div></div>
 <p v-if="error" class="alert danger" role="alert">{{error}}</p>
 <div class="stats-grid four"><article v-for="item in [{key:'pending',label:'待核查事件'},{key:'high',label:'高风险待核查'},{key:'occurrences',label:'范围内触发次数'},{key:'blocks',label:'当前来源限制'}]" :key="item.key" class="stat"><span class="stat-label">{{item.label}}</span><strong>{{data.summary[item.key]||0}}</strong><small class="muted">{{item.key==='blocks'?'全站当前生效':'按下方筛选范围统计'}}</small></article></div>
 <nav class="risk-tabs" aria-label="风控视图"><button :class="{active:panel==='events'}" @click="panel='events'">风险事件</button><button :class="{active:panel==='blocks'}" @click="panel='blocks'">当前限制</button></nav>
 <template v-if="panel==='events'"><form class="risk-filters" @submit.prevent="filter"><label>搜索客户 / 来源<input v-model="q" placeholder="客户邮箱、称呼、IP 或事件说明" maxlength="200"/></label><label>开始日期<input v-model="start" type="date"/></label><label>结束日期<input v-model="end" type="date"/></label><label>事件分类<select v-model="category"><option value="">全部分类</option><option v-for="c in data.categories" :key="c" :value="c">{{names[c]||c}}</option></select></label><label>风险级别<select v-model="severity"><option value="">全部级别</option><option value="high">高风险</option><option value="medium">需关注</option><option value="low">一般记录</option></select></label><label>处理状态<select v-model="state"><option value="">全部状态</option><option value="pending">待核查</option><option value="resolved">已核查</option></select></label><button class="btn primary" :disabled="loading">筛选</button></form>
 <p v-if="allTime" class="callout">当前显示全部时间的待核查事件。使用日期筛选后恢复按所选时间查看。</p><p class="muted small">同一客户、来源和分类在一分钟内合并计数。时间按北京时间筛选；更新于 {{date(data.generated_at)}}。</p>
 <div class="panel table-scroll"><table><thead><tr><th>最近发生</th><th>事件 / 风险</th><th>客户</th><th>来源</th><th>次数</th><th>处理</th></tr></thead><tbody><tr v-for="e in data.items" :key="e.id"><td>{{date(e.last_seen)}}</td><td><span class="badge" :class="e.severity">{{({high:'高风险',medium:'需关注',low:'记录'} as Row)[e.severity]||e.severity}}</span><button class="text-btn" @click="detail=e">{{names[e.category]||e.category}}</button><small>{{e.detail}}</small></td><td>{{e.user_name||e.email||'未登录访问'}}<small v-if="e.user_name">{{e.email}}</small></td><td class="mono">{{e.ip}}</td><td>{{e.occurrences}}</td><td><button v-if="!e.resolved" class="text-btn" :disabled="busy" @click="resolve(e.id)">标记已核查</button><span v-else class="muted">已核查</span></td></tr><tr v-if="!data.items.length"><td colspan="6" class="empty">{{loading?'正在加载…':'当前筛选范围没有风险事件'}}</td></tr></tbody></table></div>
 <div class="pagination"><span>共 {{data.total||0}} 条 · 第 {{page}} 页</span><div><button class="btn secondary" :disabled="loading||page===1" @click="page--;load()">上一页</button><button class="btn secondary" :disabled="loading||page*50>=data.total" @click="page++;load()">下一页</button></div></div></template>
 <template v-else><p class="callout">IP 限制会影响共用该来源的客户。这里只管理已经生效的限制；标记事件已核查不会自动解除限制。</p><div class="panel table-scroll"><table><thead><tr><th>访问来源</th><th>原因</th><th>自动解除时间</th><th>操作</th></tr></thead><tbody><tr v-for="b in data.blocks" :key="b.ip"><td class="mono">{{b.ip}}</td><td>{{b.reason}}</td><td>{{date(b.expires_at)}}</td><td><button class="text-btn" @click="confirmation=b">解除限制</button></td></tr><tr v-if="!data.blocks.length"><td colspan="4" class="empty">当前没有生效中的访问限制</td></tr></tbody></table></div></template>
 <Modal v-if="detail" title="风险事件详情" @close="detail=null"><dl class="risk-detail"><dt>事件说明</dt><dd>{{detail.detail}}</dd><dt>首次发生</dt><dd>{{date(detail.created_at)}}</dd><dt>最近发生</dt><dd>{{date(detail.last_seen)}}</dd><dt>触发次数</dt><dd>{{detail.occurrences}}</dd><dt>客户 / 来源</dt><dd>{{detail.email||'未登录'}} · {{detail.ip}}</dd></dl></Modal>
 <Modal v-if="confirmation" title="解除访问限制" @close="!busy&&(confirmation=null)"><p>解除 {{confirmation.ip}} 的访问限制，后续访问仍按风控规则检查。</p><button class="btn primary" :disabled="busy" @click="release">确认解除</button></Modal>
</section></template>
<style scoped>.risk-heading{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:20px}.risk-tabs{display:flex;gap:8px;margin:22px 0}.risk-tabs button{padding:10px 22px;border:1px solid #dde7e4;border-radius:8px;background:white;cursor:pointer}.risk-tabs .active{background:#276655;color:white}.risk-filters{display:flex;gap:12px;align-items:end;flex-wrap:wrap}.risk-filters label{flex:1;min-width:140px}.risk-filters label:first-child{flex:2;min-width:230px}.risk-monitor td small{display:block;color:#78908a;max-width:320px;margin-top:6px}.risk-monitor table{width:100%;min-width:780px}.risk-detail{display:grid;grid-template-columns:100px 1fr;gap:12px}.risk-detail dd{margin:0;overflow-wrap:anywhere}@media(max-width:700px){.risk-heading{align-items:stretch;flex-direction:column}.risk-filters label{min-width:40%}}</style>
